									_status.roundHistory.push({
										number: game.roundNumber,
										player: trigger.player,
										status: obj,
										event: trigger,
										cardPile: ui.cardPile.childNodes.slice(0),
										discardPile: ui.discardPile.childNodes.slice(0),
									});
