					recover_ai: {
						trigger: { player: 'changeHp' },
						silent: true,
						priority: 1000,
						firstDo: true,
						charlotte: true,
						content() {
							if (isArray(player.dyeingHp) && player.dyeingHp.length > player.hp) player.dyeingHp = player.dyeingHp.slice(0, -(player.dyeingHp.length - player.hp));
							player.update();
						},
						ai: {
							unequip: true,
							skillTagFilter(player, tag, arg) {
								if (!arg || !arg.card || arg.card.unequip !== true) return false;
							},
							effect: {
								target(card, player, target) {
									if (target.hasSkillTag('hpUnRe', null, { player: player, card: card }) && get.tag(card, 'recover')) return 'zerotarget';
									if (!target.hasMark('ark_huihai') || _status.event.getParent(2).name != 'dying' || _status.event.getParent(2).odying === false || card.name != 'tao') return;
									var cards = [];
									target.getFriends(function (current) {
										if (current.canSave(target)) cards.addArray(current.getCards('hejs', (c) => lib.filter.cardSavable(c, current, target)));
									});
									cards.addArray(target.getCards('hejs', (c) => lib.filter.cardSavable(c, target, target)));
									if (
										target == player &&
										game.findPlayer(function (current) {
											return current.hasSkill('ark_huihai') && current.hp == current.maxHp;
										})
									)
										return 0;
									if (
										cards.length < 2 &&
										game.findPlayer(function (current) {
											return current.hasSkill('ark_huihai') && current.hp == current.maxHp;
										})
									)
										return 'zerotarget';
								},
							},
						},
					},
