										suits = [];
									if (cards.length) cards.forEach((card) => suits.add(card.suit));
									if (typeof button.link == 'string') {
										return player.isHealthy || player.hasCard('tao', 'h') ? '失去体力' : '减少上限';
									}
									if (_status.event.parent.type != 'phase') return 1;
