												suits = [];
											get.discarded().forEach((card) => suits.add(card.suit));
											if (suits.length > 1 || target.countCards('h') - target.countCards('h', (card) => suits.includes(card) < 2)) return num;
											if (target.getEquip('tengjia') || target.getEquip('rewrite_tengjia')) num -= 5;
											num -= target.getDamagedHp();
