								event.goto(4);
								('step 2');
								event.current = event.targets.shift();
								var checkCard = function (c, p) {
									if (!c.isVisible()) return true;
									return lib.filter.cardDiscardable(c, p);
								};
								if (
									event.current.hasCard(function (cardx) {
										return checkCard(cardx, event.current);
									}, 'h')
								) {
									var next = event.current.chooseCard('h', true, checkCard, function (card) {
										if (_status.event.hasValueOfDiscard) {
											if (card.isVisible()) return 5 - get.value(card);
											return -1;
										}
										if (card.isVisible()) return -get.value(card);
										return 4;
									});
									next.set('hasValueOfDiscard', get.attitude(player, target) < 0 && player.countDiscardableCards(player, 'he') > 0);
								}
